function usePeriod(from, to) {
	return useQuery({
		queryKey: [
			"period",
			from,
			to
		],
		queryFn: async () => {
			const [sales, purchases, expenses, wastage] = await Promise.all([
				fetchSales(from, to),
				fetchPurchases(from, to),
				fetchExpenses(from, to),
				fetchWastage(from, to)
			]);
			return {
				sales,
				purchases,
				expenses,
				wastage
			};
		}
	});
}
function useSalesForDate(date) {
	return useQuery({
		queryKey: ["sales", date],
		queryFn: () => fetchSales(date, date)
	});
}
function invalidateAll(qc) {
	qc.invalidateQueries({ queryKey: ["period"] });
	qc.invalidateQueries({ queryKey: ["sales"] });
	qc.invalidateQueries({ queryKey: ["stock"] });
	qc.invalidateQueries({ queryKey: ["cash_day"] });
}
function useAddSale() {
	const qc = useQueryClient();
	return useMutation({
		mutationFn: async (input) => {
			const created_by = await uid();
			const { data, error } = await supabase.from("sales").insert({
				...input,
				created_by,
				client_key: newClientKey()
			}).select().single();
			if (error) throw error;
			await logAudit({
				action: "sale.created",
				entity_type: "sale",
				entity_id: data.id,
				new_value: data
			});
			return data;
		},
		onSuccess: () => invalidateAll(qc)
	});
}
function useReverseSale() {
	const qc = useQueryClient();
	return useMutation({
		mutationFn: async ({ id, reason }) => {
			const { data: before } = await supabase.from("sales").select("*").eq("id", id).single();
			const updated_by = await uid();
			const { data, error } = await supabase.from("sales").update({
				status: "reversed",
				reversal_reason: reason,
				updated_by
			}).eq("id", id).select().single();
			if (error) throw error;
			await logAudit({
				action: "sale.reversed",
				entity_type: "sale",
				entity_id: id,
				old_value: before,
				new_value: data,
				reason
			});
			return data;
		},
		onSuccess: () => invalidateAll(qc)
	});
}
