async function uploadBill(file, meta) {
	const owner = await uid();
	const ext = file.name.split(".").pop()?.toLowerCase() ?? "bin";
	if (![
		"jpg",
		"jpeg",
		"png",
		"webp",
		"pdf"
	].includes(ext)) throw new Error("Only JPG, PNG, WEBP or PDF files are allowed");
	if (file.size > 15728640) throw new Error("File must be under 15 MB");
	const path = `${owner}/${Date.now()}-${crypto.randomUUID()}.${ext}`;
	const { error: upErr } = await supabase.storage.from("bills").upload(path, file, {
		contentType: file.type || "application/octet-stream",
		upsert: false
	});
	if (upErr) throw upErr;
	const { data, error } = await supabase.from("documents").insert({
		storage_path: path,
		file_name: file.name,
		mime_type: file.type,
		size_bytes: file.size,
		uploaded_by: owner,
		...meta
	}).select().single();
	if (error) throw error;
	await logAudit({
		action: "document.uploaded",
		entity_type: "document",
		entity_id: data.id,
		new_value: data
	});
	return data;
}
